import { createHash, randomBytes } from "node:crypto";
import { z } from "zod";

// Scalable Capital's official MCP server. OAuth 2.1 with dynamic client registration and PKCE
// (public client, no secret); the bearer token then calls MCP tools over Streamable HTTP.
// Hosted redirect URIs must be on Scalable's SaaS allowlist; localhost registers freely.
const ISSUER = "https://mcp.scalable.capital";
export const SCALABLE_MCP_URL = `${ISSUER}/mcp`;
const SCOPE = "openid profile offline_access";
const PROTOCOL_VERSION = "2025-06-18";

export class ScalableError extends Error {
  constructor(message: string, readonly status: number, readonly expired = false) { super(message); }
}

const base64url = (bytes: Buffer) => bytes.toString("base64url");

export function pkcePair() {
  const verifier = base64url(randomBytes(32));
  return { verifier, challenge: base64url(createHash("sha256").update(verifier).digest()) };
}

async function json<T>(response: Response, schema: z.ZodType<T>): Promise<T> {
  const body = await response.json().catch(() => null);
  if (!response.ok) {
    const code = z.object({ error: z.string() }).safeParse(body).data?.error;
    throw new ScalableError(`Scalable returned ${response.status}${code ? ` (${code})` : ""}`, response.status, code === "invalid_grant" || response.status === 401);
  }
  return schema.parse(body);
}

export async function registerClient(redirectUri: string, fetcher: typeof fetch = fetch) {
  const response = await fetcher(`${ISSUER}/register`, {
    method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ client_name: "Moneo", redirect_uris: [redirectUri], grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"], token_endpoint_auth_method: "none", scope: SCOPE }),
  });
  return (await json(response, z.object({ client_id: z.string().min(1).max(200) }))).client_id;
}

export function authorizeUrl(input: { clientId: string; redirectUri: string; state: string; challenge: string }) {
  const url = new URL(`${ISSUER}/authorize`);
  url.search = new URLSearchParams({ response_type: "code", client_id: input.clientId, redirect_uri: input.redirectUri, scope: SCOPE,
    state: input.state, code_challenge: input.challenge, code_challenge_method: "S256", resource: SCALABLE_MCP_URL }).toString();
  return url.toString();
}

export type ScalableTokens = { accessToken: string; refreshToken: string | null; expiresAt: number };
const tokenSchema = z.object({ access_token: z.string().min(1), refresh_token: z.string().min(1).optional(), expires_in: z.number().positive().optional() });

async function token(params: Record<string, string>, fetcher: typeof fetch, previousRefresh: string | null = null): Promise<ScalableTokens> {
  const response = await fetcher(`${ISSUER}/token`, {
    method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ ...params, resource: SCALABLE_MCP_URL }).toString(),
  });
  const body = await json(response, tokenSchema);
  // Without expires_in, assume a short life so the next call refreshes instead of failing.
  return { accessToken: body.access_token, refreshToken: body.refresh_token ?? previousRefresh, expiresAt: Date.now() + (body.expires_in ?? 300) * 1000 };
}

export const exchangeCode = (input: { clientId: string; redirectUri: string; code: string; verifier: string }, fetcher: typeof fetch = fetch) =>
  token({ grant_type: "authorization_code", client_id: input.clientId, redirect_uri: input.redirectUri, code: input.code, code_verifier: input.verifier }, fetcher);

export const refreshTokens = (input: { clientId: string; refreshToken: string }, fetcher: typeof fetch = fetch) =>
  token({ grant_type: "refresh_token", client_id: input.clientId, refresh_token: input.refreshToken }, fetcher, input.refreshToken);

const rpcSchema = z.object({ id: z.union([z.number(), z.string()]).optional(), result: z.unknown().optional(), error: z.object({ message: z.string() }).optional() });

/** The JSON-RPC answer to `id`, from a plain JSON body or a Server-Sent Events stream. */
export function rpcMessage(text: string, contentType: string, id: number) {
  const messages = contentType.includes("text/event-stream")
    ? text.split(/\r?\n/).filter(line => line.startsWith("data:")).map(line => line.slice(5).trim()).filter(Boolean).map(data => JSON.parse(data) as unknown)
    : [JSON.parse(text) as unknown];
  const message = messages.map(item => rpcSchema.safeParse(item).data).find(item => item?.id === id);
  if (!message) throw new ScalableError("Scalable MCP sent no answer", 502);
  if (message.error) throw new ScalableError(`Scalable MCP: ${message.error.message}`, 502);
  return message.result;
}

const toolResultSchema = z.object({
  content: z.array(z.object({ type: z.string(), text: z.string().optional() })).default([]),
  structuredContent: z.unknown().optional(), isError: z.boolean().optional(),
});

/** Read-only MCP session. Tool results are structured content, or the text content parsed as JSON when possible. */
export function scalableMcp(accessToken: string, fetcher: typeof fetch = fetch) {
  let sessionId: string | null = null, protocol = PROTOCOL_VERSION, nextId = 0;
  async function rpc(method: string, params?: unknown, notification = false) {
    const id = ++nextId;
    const response = await fetcher(SCALABLE_MCP_URL, {
      method: "POST",
      headers: { authorization: `Bearer ${accessToken}`, "content-type": "application/json", accept: "application/json, text/event-stream",
        "mcp-protocol-version": protocol, ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
      body: JSON.stringify(notification ? { jsonrpc: "2.0", method, params } : { jsonrpc: "2.0", id, method, params }),
    });
    if (!response.ok) throw new ScalableError(`Scalable MCP returned ${response.status}`, response.status, response.status === 401);
    sessionId = response.headers.get("mcp-session-id") ?? sessionId;
    if (notification) return undefined;
    return rpcMessage(await response.text(), response.headers.get("content-type") ?? "", id);
  }
  return {
    async connect() {
      const result = z.object({ protocolVersion: z.string() }).parse(await rpc("initialize", { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "Moneo", version: "1.0.0" } }));
      protocol = result.protocolVersion;
      await rpc("notifications/initialized", undefined, true);
    },
    listTools: async () => z.object({ tools: z.array(z.object({ name: z.string() }).passthrough()) }).parse(await rpc("tools/list", {})).tools,
    async callTool(name: string, args: Record<string, unknown> = {}): Promise<unknown> {
      const result = toolResultSchema.parse(await rpc("tools/call", { name, arguments: args }));
      const text = result.content.filter(item => item.type === "text").map(item => item.text ?? "").join("\n");
      if (result.isError) throw new ScalableError(`Scalable tool ${name} failed: ${text.slice(0, 300)}`, 502);
      if (result.structuredContent !== undefined) return result.structuredContent;
      try { return JSON.parse(text) as unknown; } catch { return text; }
    },
  };
}
export type ScalableMcp = ReturnType<typeof scalableMcp>;
import { createHash } from "node:crypto";
import { z } from "zod";
import { minorDigits } from "@/lib/finance/fx";
import { holdingValue } from "@/lib/finance/wealth";

// Scalable MCP answers, validated down to the fields Moneo uses. Amounts arrive as JSON numbers.
const money = z.number().finite();
export const holdingsSchema = z.object({
  holdings: z.array(z.object({
    isin: z.string().min(1), name: z.string().min(1), fifoPrice: money.nullable().optional(), valuation: money, valuationCurrency: z.string().regex(/^[A-Z]{3}$/),
    currentQuote: z.object({ currency: z.string().regex(/^[A-Z]{3}$/), midPrice: money }), position: z.object({ filled: money }),
  })),
  cryptoHoldings: z.array(z.object({ ticker: z.string(), name: z.string(), position: z.object({ filled: money }).nullable() })).default([]),
});
export const overviewSchema = z.object({
  valuation: z.object({ total: money, securities: money.default(0), crypto: money.default(0) }),
  timestamps: z.object({ valuationTimestampUtc: z.string() }).partial().optional(),
  performance: z.array(z.object({ timeframe: z.string(), simpleAbsoluteReturn: money.nullable() })).default([]),
});
export const cashSchema = z.object({ cash: z.object({ cashBalance: money }) });

export type ScalableSnapshot = { holdings: z.infer<typeof holdingsSchema>; overview: z.infer<typeof overviewSchema>; cash: z.infer<typeof cashSchema> };

/** Shortest exact decimal text for a JSON number (never exponent notation). */
export function decimalText(value: number) {
  const text = String(Math.abs(value));
  return text.includes("e") ? Math.abs(value).toFixed(18).replace(/\.?0+$/, "") : text;
}
const minor = (value: number, currency: string) => BigInt(Math.round(value * 10 ** minorDigits(currency)));

/** Same workspace + position key → same wealth item id, so every sync and every reconnect updates one record. */
export function scalableItemId(workspaceId: string, key: string) {
  const hex = createHash("sha256").update(`scalable:${workspaceId}:${key}`).digest("hex");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-5${hex.slice(13, 16)}-${((parseInt(hex[16], 16) & 3) | 8).toString(16)}${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
}

export type ScalableWealthItem = { id: string; kind: "holding" | "asset"; name: string; currency_code: string; amount_minor: string;
  quantity_text: string | null; unit_price_text: string | null; cost_basis_minor: string | null; as_of: string };

/**
 * Wealth records for one Scalable portfolio on `asOf`: each security at quantity × live price,
 * plus uninvested cash and crypto as assets. Their sum is Scalable's own portfolio total (to the cent).
 */
export function scalableWealth({ holdings, overview, cash }: ScalableSnapshot, workspaceId: string, asOf: string, currency = "EUR") {
  const items: ScalableWealthItem[] = holdings.holdings.filter(holding => holding.position.filled > 0).map(holding => {
    const quantity = decimalText(holding.position.filled), price = decimalText(holding.currentQuote.midPrice), code = holding.currentQuote.currency;
    return { id: scalableItemId(workspaceId, `isin:${holding.isin}`), kind: "holding", name: Array.from(holding.name).slice(0, 120).join(""), currency_code: code,
      amount_minor: holdingValue(quantity, price, code).toString(), quantity_text: quantity, unit_price_text: price,
      cost_basis_minor: holding.fifoPrice ? minor(holding.fifoPrice * holding.position.filled, code).toString() : null, as_of: asOf };
  });
  const asset = (key: string, name: string, value: number): ScalableWealthItem => ({ id: scalableItemId(workspaceId, key), kind: "asset", name, currency_code: currency,
    amount_minor: minor(Math.max(value, 0), currency).toString(), quantity_text: null, unit_price_text: null, cost_basis_minor: null, as_of: asOf });
  const coins = holdings.cryptoHoldings.filter(coin => (coin.position?.filled ?? 0) > 0).map(coin => coin.name);
  if (overview.valuation.crypto > 0) items.push(asset("crypto", `Scalable crypto${coins.length ? ` (${coins.join(", ")})` : ""}`.slice(0, 120), overview.valuation.crypto));
  items.push(asset("cash", "Scalable cash", cash.cash.cashBalance));
  const portfolio = {
    currency, asOf, valuedAt: overview.timestamps?.valuationTimestampUtc ?? null,
    totalMinor: minor(overview.valuation.total, currency).toString(), securitiesMinor: minor(overview.valuation.securities, currency).toString(),
    cryptoMinor: minor(overview.valuation.crypto, currency).toString(), cashMinor: minor(cash.cash.cashBalance, currency).toString(),
    performance: overview.performance.flatMap(entry => entry.simpleAbsoluteReturn === null ? [] : [{ timeframe: entry.timeframe, returnMinor: minor(entry.simpleAbsoluteReturn, currency).toString() }]),
  };
  return { items, portfolio };
}
export type ScalablePortfolio = ReturnType<typeof scalableWealth>["portfolio"];
import { serviceDb } from "@/lib/bank/server";
import { decryptToken, encryptToken } from "@/lib/bank/token-crypto";
import { getEnv } from "@/lib/env";
import { refreshTokens, scalableMcp, ScalableError, type ScalableMcp, type ScalableTokens } from "./client";

export const scalableRedirectUri = () => new URL("/api/scalable/callback", getEnv().NEXT_PUBLIC_APP_URL).toString();

export function scalableConfigured() {
  return Boolean(process.env.BANK_TOKEN_ENCRYPTION_KEY && process.env.SUPABASE_SERVICE_ROLE_KEY);
}

export const sealTokens = (tokens: ScalableTokens, connectionId: string) => encryptToken(JSON.stringify(tokens), connectionId);
const openTokens = (sealed: string, connectionId: string) => JSON.parse(decryptToken(sealed, connectionId)) as ScalableTokens;

/**
 * Runs `work` with a connected MCP session for an active connection. Refreshes the access token
 * when it is about to expire and stores the rotated tokens first, so a crash never loses them.
 * A rejected refresh marks the connection expired: the owner has to connect again.
 */
export async function withScalable<T>(connectionId: string, workspaceId: string, work: (mcp: ScalableMcp) => Promise<T>, fetcher: typeof fetch = fetch): Promise<T> {
  const db = serviceDb();
  const row = await db.from("scalable_connections").select("client_id, tokens_encrypted").eq("id", connectionId)
    .eq("workspace_id", workspaceId).eq("status", "active").single();
  if (row.error || !row.data?.tokens_encrypted) throw new ScalableError("Scalable is not connected", 404);
  let tokens = openTokens(row.data.tokens_encrypted, connectionId);
  if (tokens.expiresAt - Date.now() < 60_000) {
    if (!tokens.refreshToken) return expire(connectionId, "The Scalable login ended. Connect again.");
    try { tokens = await refreshTokens({ clientId: row.data.client_id, refreshToken: tokens.refreshToken }, fetcher); } catch (error) {
      if (error instanceof ScalableError && error.expired) return expire(connectionId, "The Scalable login ended. Connect again.");
      throw error;
    }
    const saved = await db.from("scalable_connections").update({ tokens_encrypted: sealTokens(tokens, connectionId) }).eq("id", connectionId).eq("status", "active");
    if (saved.error) throw new Error(saved.error.message);
  }
  const mcp = scalableMcp(tokens.accessToken, fetcher);
  try {
    await mcp.connect();
    return await work(mcp);
  } catch (error) {
    if (error instanceof ScalableError && error.expired) return expire(connectionId, "Scalable rejected the login. Connect again.");
    throw error;
  }
}

async function expire(connectionId: string, message: string): Promise<never> {
  await serviceDb().from("scalable_connections").update({ status: "expired", tokens_encrypted: null, last_error: message }).eq("id", connectionId);
  throw new ScalableError(message, 401, true);
}
import { serviceDb } from "@/lib/bank/server";
import { calendarDate } from "@/lib/finance/calendar";
import { loadWorkspaceSettings } from "@/lib/settings";
import { ScalableError } from "./client";
import { cashSchema, holdingsSchema, overviewSchema, scalableWealth } from "./portfolio";
import { withScalable } from "./server";

/**
 * One sync: read holdings, totals and cash from Scalable, then write them as dated wealth records in
 * one database call. Market moves are valuations, not income; deposits and withdrawals are transfers
 * on the bank side. Errors are kept on the connection for the UI and rethrown.
 */
export async function syncScalable(connectionId: string, workspaceId: string) {
  const db = serviceDb();
  try {
    const { timezone } = await loadWorkspaceSettings(db, workspaceId);
    const snapshot = await withScalable(connectionId, workspaceId, async mcp => {
      const [holdings, overview, cash] = await Promise.all([mcp.callTool("get_portfolio_holdings"), mcp.callTool("get_portfolio_overview"), mcp.callTool("get_portfolio_cash_breakdown")]);
      return { holdings: holdingsSchema.parse(holdings), overview: overviewSchema.parse(overview), cash: cashSchema.parse(cash) };
    });
    const { items, portfolio } = scalableWealth(snapshot, workspaceId, calendarDate(new Date(), timezone));
    const { data, error } = await db.rpc("sync_scalable_wealth", { p_connection_id: connectionId, p_items: items, p_portfolio: portfolio });
    if (error) throw new Error(error.message);
    return { changed: data as number, portfolio };
  } catch (error) {
    // An ended login is already recorded as expired by withScalable.
    if (!(error instanceof ScalableError && error.expired))
      await db.from("scalable_connections").update({ last_error: "The Scalable sync failed. It retries on the next sync." }).eq("id", connectionId);
    throw error;
  }
}
