-- Lets chat propose a balance (balance_set) as a card; accepting it records the balance through record_manual_balance.
alter table public.agent_proposals drop constraint agent_proposals_kind_check;
alter table public.agent_proposals add constraint agent_proposals_kind_check check (kind in ('categorize','recurring','budget','finding','iou_create','iou_settle','transaction_create','balance_set'));
drop policy own_agent_proposals_standalone_insert on public.agent_proposals;
create policy own_agent_proposals_standalone_insert on public.agent_proposals for insert to authenticated
  with check (public.owns_workspace(workspace_id) and run_id is null and kind in ('iou_create','iou_settle','transaction_create','balance_set') and status = 'proposed');
  const { data, error } = await supabase.from("agent_proposals").insert({ workspace_id: workspace.id, agent: "chat", kind: "balance_set", ...(chatRequestId ? { chat_request_id: chatRequestId } : {}), 
    conflict_key: `balance_set:${crypto.randomUUID()}`, title, detail: asOf === today ? "Today" : asOf, payload, confidence: 100 }).select("id").single();
  if (error) throw new Error(error.message);
  return { proposalId: data.id as string, title };
}

/** Records the accepted balance through the same audited RPC as Accounts; the proposal id is the request id, so accepting twice cannot duplicate it. */
export async function applyBalanceProposal({ supabase, workspace }: Context, proposalId: string, payload: unknown) {
  const parsed = balanceSetSchema.parse(payload);
  let accountId = parsed.accountId, createdAccount = false;
  if (accountId) {
    const account = await supabase.from("accounts").select("currency_code").eq("workspace_id", workspace.id).eq("id", accountId).is("archived_at", null).maybeSingle();
    if (account.error || !account.data) throw new Error("Account not found");
    if (account.data.currency_code !== parsed.currencyCode) throw new Error(`Choose an account in ${parsed.currencyCode}`);
  } else {
    const created = await supabase.from("accounts").insert({ workspace_id: workspace.id, name: "Cash", type: "cash", currency_code: parsed.currencyCode }).select("id").single();
    if (created.error) throw new Error(created.error.message);
    accountId = created.data.id as string; createdAccount = true;
  }
  // The RPC refuses the write if the history changed since this read, so the owner is never overwriting an unseen balance.
  const latest = await supabase.from("balance_snapshots").select("id, version").eq("workspace_id", workspace.id).eq("account_id", accountId)
    .order("created_at", { ascending: false }).order("id", { ascending: false }).limit(1).maybeSingle();
  if (latest.error) throw new Error(latest.error.message);
  const { error } = await supabase.rpc("record_manual_balance", { p_account_id: accountId, p_amount_minor: parsed.amountMinor, p_date: parsed.asOf,
    p_reviewed: false, p_covered_transactions: null, p_expected_snapshot_id: latest.data?.id ?? null, p_expected_version: latest.data?.version ?? 0, p_request_id: proposalId });
  if (error) throw new Error(error.message);
  return { href: "/money/accounts", undo: "Undo the balance on Accounts", accountId, createdAccount };
}
import type { SupabaseClient } from "@supabase/supabase-js";
import { transactionAccountOptions } from "@/lib/ai/transaction-proposals";

/** Card kinds that live outside an agent run: raised by chat or detection, decided one at a time. */
export const STANDALONE_KINDS = ["iou_create", "iou_settle", "transaction_create", "balance_set", "recurring_edit"];

/** Card ids an assistant answer shows in its moneo-proposal(s) blocks. */
export function answerCardIds(content: string | null | undefined): string[] {
  return [...(content ?? "").matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []);
}

/** A bank transaction a card is about (a repayment, a flagged charge), shown under the card so it can be decided there. */
export type CardTransaction = { id: string; date: string; description: string; amountMinor: string; currency: string };
export type OpenProposal = { id: string; kind: string; title: string; detail: string; status: string; conflict_key?: string; accounts?: { id: string; name: string }[]; selected?: string | null; createsCash?: boolean;
  transactions?: CardTransaction[] };

export const cardTransactions = (evidence: unknown): CardTransaction[] => {
  const rows = (evidence as { transactions?: unknown } | null)?.transactions;
  return Array.isArray(rows) ? rows.filter((row): row is CardTransaction => typeof row?.id === "string" && typeof row?.amountMinor === "string").slice(0, 8) : [];
};

/** Every open standalone card, oldest first, as IouCard shows it; an expense card carries the accounts it can be paid from. */
export async function openStandaloneProposals(supabase: SupabaseClient, workspaceId: string): Promise<OpenProposal[]> {
  const { data, error } = await supabase.from("agent_proposals").select("id, kind, title, detail, status, conflict_key, payload, evidence").eq("workspace_id", workspaceId).is("run_id", null)
    .in("kind", STANDALONE_KINDS).in("status", ["proposed", "failed"]).order("created_at").limit(100);
  if (error) throw new Error(error.message);
  return Promise.all((data ?? []).map(async ({ payload, evidence, ...row }) => {
    const transactions = cardTransactions(evidence), proposal = transactions.length ? { ...row, transactions } : row;
    // Without options the card still accepts into the proposed account, so one unreadable payload does not hide the rest.
    return proposal.kind === "transaction_create" ? { ...proposal, ...await transactionAccountOptions(supabase, workspaceId, payload).catch(() => ({})) } : proposal;
  }));
}

import type { requireWorkspace } from "@/lib/auth";
import { loadOrganizationSuggestions } from "@/lib/import/organization-loader";
import { payloadSchemas, type ProposalKind } from "@/lib/ai/agent-team";
import { calendarDate } from "@/lib/finance/calendar";
import { iouCreateSchema, iouRecord, iouSettleSchema, parseIouName, settledRecord } from "@/lib/finance/iou";
import { applyTransactionProposal } from "@/lib/ai/transaction-proposals";
import { applyBalanceProposal } from "@/lib/ai/balance-proposals";
import { applyRecurringProposal, dismissRecurringProposal } from "@/lib/ai/recurring-proposals";
import type { ScheduleFields } from "@/app/money/recurring/schedules";

// Accepting a proposal calls the SAME audited RPCs a person uses by hand, as
// the signed-in owner (auth.uid()), so corrections, batches and Undo stay intact.
type Context = Awaited<ReturnType<typeof requireWorkspace>>;
export type StoredProposal = { id: string; kind: ProposalKind | "iou_create" | "iou_settle" | "transaction_create" | "balance_set" | "recurring_edit"; payload: unknown };
/** Choices made on the card itself: the account a chat expense is paid from, or what the person set when confirming a recurring payment. */
export type DecideOptions = { accountId?: string; recurring?: Partial<ScheduleFields> };
export type Applied = { href: string; undo?: string; [key: string]: unknown };

export async function applyProposal(context: Context, proposal: StoredProposal, options: DecideOptions = {}): Promise<Applied> {
  const { supabase, workspace } = context;
  switch (proposal.kind) {
    case "categorize": {
      const payload = payloadSchemas.categorize.parse(proposal.payload);
      // Same guard as a manual organization review: corrections and complete rows take precedence.
      const current = await loadOrganizationSuggestions(supabase, workspace.id, payload.rows);
      if (current.proposals.length !== payload.rows.length) throw new Error("Some rows were corrected or organized since the agent ran");
      const evidence = [...new Map(current.proposals.flatMap(item => item.evidence).map(row => [row.id, row])).values()];
      const created = await supabase.rpc("create_organization_review", { p_rows: payload.rows, p_patch: payload.patch, p_merchant_name: payload.merchantName,
        p_rule_key: payload.ruleKey, p_evidence: evidence, p_request_id: proposal.id });
      if (created.error) throw new Error(created.error.message);
      const reviewId = String(created.data.id);
      const applied = await supabase.rpc("apply_organization_review", { p_review_id: reviewId, p_save_rule: payload.ruleKey !== null });
      if (applied.error) throw new Error(applied.error.message);
      return { reviewId, href: `/money/organization?review=${reviewId}`, undo: "Undo from the organization review" };
    }
    case "recurring": {
      const payload = payloadSchemas.recurring.parse(proposal.payload);
      const { error } = await supabase.rpc("review_recurring_series_versions", { p_decision: "confirmed", p_account_id: payload.accountId, p_label: payload.label,
        p_cadence: payload.cadence, p_currency_code: payload.currencyCode, p_evidence: payload.evidence, p_run_anchor_id: payload.runAnchorId, p_evidence_limited: payload.evidenceLimited });
      if (error) throw new Error(error.message);
      return { href: "/money/recurring", undo: "Choose “Not recurring” on the Recurring page" };
    }
    case "budget": {
      const payload = payloadSchemas.budget.parse(proposal.payload);
      const category = await supabase.from("categories").select("id").eq("workspace_id", workspace.id).eq("id", payload.categoryId).maybeSingle();
      if (category.error || !category.data) throw new Error("Category not found");
      // Same insert as Plan → Spending limits; a target only, never touches balances or goals.
      const { error } = await supabase.from("spending_plans").insert({ workspace_id: workspace.id, category_id: payload.categoryId, currency_code: payload.currencyCode,
        limit_minor: payload.limitMinor, enabled: true, updated_at: new Date().toISOString() });
      if (error?.code === "23505") throw new Error("A limit already exists for this category and currency");
      if (error) throw new Error(error.message);
      return { href: "/plan/spending", undo: "Turn the limit off in Plan → Spending" };
    }
    case "iou_create": {
      // The proposal id is both the new item's id and the request id, so accepting twice cannot duplicate it.
      const record = iouRecord(iouCreateSchema.parse(proposal.payload));
      const { error } = await supabase.rpc("edit_wealth_item", { p_id: proposal.id, p_expected_version: 0, p_record: record, p_remove: false, p_request_id: proposal.id });
      if (error) throw new Error(error.message);
      return { href: "/money/wealth", undo: "Undo from the Wealth history" };
    }
    case "iou_settle": {
      const payload = iouSettleSchema.parse(proposal.payload);
      const [item, transaction] = await Promise.all([
        supabase.from("wealth_items").select("id, kind, name, currency_code, amount_minor::text, as_of, version, removed_at, linked_account_id, annual_rate_text, monthly_payment_minor::text")
          .eq("workspace_id", workspace.id).eq("id", payload.itemId).is("removed_at", null).maybeSingle(),
        supabase.from("transactions").select("id, amount_minor::text, currency_code").eq("workspace_id", workspace.id).eq("id", payload.transactionId).maybeSingle(),
      ]);
      if (item.error || !item.data || !parseIouName(item.data.name)) throw new Error("This loan changed or was removed since the repayment was found");
      const paid = transaction.data ? BigInt(transaction.data.amount_minor) : 0n;
      const lent = item.data.kind === "asset";
      if (transaction.data?.currency_code !== item.data.currency_code || (lent ? paid <= 0n : paid >= 0n) || BigInt(payload.appliedMinor) > (paid < 0n ? -paid : paid))
        throw new Error("The transaction no longer matches this repayment");
      const next = settledRecord(item.data, payload.appliedMinor, calendarDate(new Date(), workspace.timezone));
      const { error } = await supabase.rpc("edit_wealth_item", { p_id: item.data.id, p_expected_version: item.data.version, p_record: next ?? {}, p_remove: next === null, p_request_id: proposal.id });
      if (error) throw new Error(error.message);
      return { href: "/money/wealth", undo: "Undo from the Wealth history" };
    }
    case "transaction_create":
      return applyTransactionProposal(context, proposal.id, proposal.payload, options.accountId);
    case "balance_set":
      return applyBalanceProposal(context, proposal.id, proposal.payload);
    case "recurring_edit":
      return applyRecurringProposal(context, proposal.id, proposal.payload, options.recurring);
    case "finding":
      payloadSchemas.finding.parse(proposal.payload);
      return { href: "/money/transactions", acknowledged: true };
  }
}

/**
 * A message a person can act on. When the database or its proxy is unreachable the client hands back an HTML error page
 * (a Cloudflare 5xx screen), which is no use on a card.
 */
export function readableError(cause: unknown) {
  const message = cause instanceof Error || (typeof cause === "object" && cause && "message" in cause) ? String((cause as { message: unknown }).message) : String(cause);
  return /<(!doctype|html|head|body)\b/i.test(message) || /cloudflare/i.test(message) ? "The database did not answer. Nothing was saved; try again in a moment." : message.slice(0, 500);
}

/** Claims each proposal once, applies it, and records the outcome. Rejecting only changes a dismissed recurring pattern's review state. */
export async function decideProposals(context: Context, ids: string[], decision: "accept" | "reject", options: DecideOptions = {}) {
  const { supabase, workspace } = context;
  const outcomes: { id: string; status: string; error?: string }[] = [];
  for (const id of ids) {
    const now = new Date().toISOString();
    if (decision === "reject") {
      // A dismissed recurring pattern is remembered on the series first; if that fails the card stays open to try again.
      // Dismissing a price change only keeps the old amount.
      const open = await supabase.from("agent_proposals").select("conflict_key, payload").eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"]).maybeSingle();
      const dismissed = open.data && String(open.data.conflict_key).startsWith("recurring_new:")
        ? await dismissRecurringProposal(context, id, open.data.payload).then(() => undefined, (cause: unknown) => readableError(cause)) : undefined;
      if (open.error || dismissed) { outcomes.push({ id, status: "failed", error: open.error ? readableError(open.error) : dismissed }); continue; }
      const { data, error } = await supabase.from("agent_proposals").update({ status: "rejected", decided_at: now }).eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"])
        .select("id").maybeSingle();
      outcomes.push({ id, status: error ? "failed" : data ? "rejected" : "unchanged", ...(error ? { error: readableError(error) } : {}) });
      continue;
    }
    const claim = await supabase.from("agent_proposals").update({ status: "applying", decided_at: now }).eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"])
      .select("id, kind, payload").maybeSingle();
    if (claim.error || !claim.data) { outcomes.push({ id, status: "unchanged", ...(claim.error ? { error: claim.error.message } : {}) }); continue; }
    let result: Applied;
    try { result = await applyProposal(context, claim.data as StoredProposal, options); }
    catch (cause) {
      const message = readableError(cause);
      await supabase.from("agent_proposals").update({ status: "failed", result: { error: message } }).eq("id", id).eq("workspace_id", workspace.id).eq("status", "applying");
      outcomes.push({ id, status: "failed", error: message });
      continue;
    }
    const saved = await supabase.from("agent_proposals").update({ status: "accepted", result, decided_at: new Date().toISOString() }).eq("id", id).eq("workspace_id", workspace.id).eq("status", "applying");
    outcomes.push({ id, status: "accepted", ...(saved.error ? { error: `Applied, but the review record was not updated: ${saved.error.message}` } : {}) });
  }
  return outcomes;
}
