  transactions_previewCategory: "Preview category change",
  transactions_setCategory: "Apply selected category change",
  finance_investigate: "Investigate transactions", finance_entities: "Resolve accounts, categories and merchants",
  finance_detail: "Read transaction detail", finance_scenario: "Compare a what-if scenario", plan_investigation: "Plan the investigation",
  write_page: "Design the page", card_preset: "Make a Home card", write_card: "Design a Home card", remove_card: "Remove a Home card",
};

export type ToolStep = { id?: string; name: string; state: "running" | "done" | "failed"; input?: unknown; output?: string };

/** One-line gist of a tool input: its first few short scalar values, e.g. "spending · Netto · 2026-10-01". */
export function toolSummary(input: unknown): string {
  const values: string[] = [];
  const walk = (value: unknown) => {
    if (values.length >= 4 || value === null || value === undefined) return;
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") { const text = String(value); if (text && text.length <= 40) values.push(text); }
    else if (Array.isArray(value)) value.forEach(walk);
    else if (typeof value === "object") Object.values(value).forEach(walk);
  };
  walk(input);
  return values.join(" · ");
}

const block = "mt-1 max-h-60 max-w-full overflow-auto whitespace-pre rounded-md bg-muted p-2 font-mono text-[11px] text-foreground";
/** What chat tells people about Moneo itself. Keep in step with the navigation in components/app-shell.tsx. */
export const APP_GUIDE = `Moneo is a personal-finance workspace. Pages (link with these paths):
- Overview (/): net worth chart, account balances, cash flow by month, coming payments, goals, budgets and the agent briefing.
- Transactions (/money/transactions): every transaction. Open one to edit its category, merchant, note or tags, split it, link a transfer or refund, or Undo a change. "Add transaction" records cash or other manual entries.
- Organization (/money/organization): give merchants and categories to unorganized rows in bulk, optionally saving a rule.
- Investigations (/money/investigations): saved, exact answers to finance questions.
- Import (/import): drop CSV or XLSX bank exports; rows are matched, deduplicated and reviewed before they count. Connected banks there syncs EU banks through Enable Banking; the owner pastes the Enable Banking App ID and private key there once.
- Accounts (/money/accounts): add, rename or archive accounts and set a dated balance (chat can propose one for the user to save). Balances roll forward with later transactions; an account without a balance is left out of net worth.
- Recurring (/money/recurring): recurring bills, subscriptions and income, each with an amount, direction, cadence, next date and category (e.g. Job). Confirm detected suggestions, click one to edit or remove it, or Add recurring. In chat, say "add Netflix 12.99 monthly", "my salary is now 3300" or "remove the gym from recurring" to get a card.
- Plan (/plan): cash-flow forecast, goals and scenarios. Spending (/plan/spending): monthly category limits. Currency (/plan/currency): display currency and manual exchange rates.
- Wealth (/money/wealth): investments, assets, debts and money lent to or borrowed from people; these count in net worth.
- Ask (/ai): this chat. The Ask Moneo panel on other pages is the same chat.
- Agent team (/ai/agents): a team of agents (categorizer, recurring detective, anomaly hunter, budget coach, forecaster, insight writer) reviews your data after imports or on request and proposes changes you accept or dismiss. Activity log (/ai/activity): what AI did.
- Artifacts (/ai/artifacts): interactive pages, calculators and dashboards built on request, each in its own chat; any of them can become a card on Home (preview it, pick a size, then Add to Home).
- Notifications (/notifications) and Settings (/settings): AI access (Sign in with ChatGPT, or an OpenAI or OpenRouter API key entered there; voice calls and dictation need the OpenAI key), timezone, locale, theme, AI models, which data AI may read, and scheduled summaries.
In chat you can: ask about your money; say what you spent or received ("I spent €10 on lunch") or attach a receipt photo or PDF to get a card that adds it to Transactions; say you lent or borrowed money to add it to Wealth; ask what the agent team found and accept or dismiss it; ask for charts or an interactive page. Nothing changes until you press the card's button, and every change can be undone.
Keyboard: Ctrl/⌘+K opens the command palette, ? shows shortcuts, G then a letter jumps to a page.`;

