// Owner's real Scalable account: reads and an order PREVIEW only. The Buy button is never pressed, and any
// accept request is aborted by the route below as a second guard.
import { expect, test, type Page } from "@playwright/test";
const shot = (page: Page, name: string) => page.screenshot({ path: `.qa/shots/real-${name}.png` });
async function ask(page: Page, question: string) {
  const box = page.locator("main").getByLabel("Ask about your finances");
  await box.click(); await box.pressSequentially(question, { delay: 25 });
  await page.locator("main").getByRole("button", { name: "Send", exact: true }).click();
}
test("real account demo (preview only)", async ({ page }) => {
  test.setTimeout(400_000);
  let blocked = 0;
  await page.route("**/*", async route => {
    const request = route.request();
    if (request.method() === "POST" && request.headers()["next-action"] && /"accept"/.test(request.postData() ?? "")) { blocked++; return route.abort(); }
    return route.continue();
  });
  await page.request.post("/api/scalable/connections/3736c267-712a-4c33-8c08-e2239ed7f8f7/sync");
  await page.goto("/money/wealth");
  const panel = page.getByRole("region", { name: "Scalable Capital" });
  await panel.scrollIntoViewIfNeeded(); await page.waitForTimeout(1500); await shot(page, "wealth-top");
  await page.mouse.wheel(0, 500); await page.waitForTimeout(1500); await shot(page, "wealth-positions");
  await page.goto("/ai?conversation=new");
  await ask(page, "How is my Scalable portfolio doing, and how much cash do I have left to invest?");
  await expect(page.getByText("Used", { exact: false }).first()).toBeVisible({ timeout: 90_000 });
  await page.waitForTimeout(12000); await shot(page, "chat-portfolio");
  await ask(page, "Buy 1 share of iShares STOXX Europe 600 Technology at market");
  const card = page.getByRole("region", { name: "Buy card" });
  await expect(card).toBeVisible({ timeout: 120_000 });
  await card.scrollIntoViewIfNeeded(); await page.waitForTimeout(3000); await shot(page, "card");
  await card.getByText("Scalable's full review").click(); await page.waitForTimeout(3000); await shot(page, "card-review");
  await card.getByRole("button", { name: /^Dismiss:/ }).click();
  await expect(card.getByRole("status")).toContainText("Nothing was sent", { timeout: 30_000 });
  await page.waitForTimeout(2500); await shot(page, "card-dismissed");
  expect(blocked).toBe(0);
});
EOF
